{
  "kc_id": "KC_CLU_EVAL_002",
  "canonical_name": "SSE (Cluster Quality)",
  "definition": {
    "status": "grounded",
    "text": "Sum of the squared error (SSE), also known as scatter, is an objective function used to measure the quality of a clustering; it is calculated by computing the error of each data point (its Euclidean distance to the closest centroid) and then computing the total sum of the squared errors.",
    "supporting_evidence_ids": [
      "E2"
    ],
    "abstention_reason": ""
  },
  "scope": {
    "status": "grounded",
    "text": "Lower SSE translates into noticeably better clustering results, and a smaller squared error indicates that the prototypes (centroids) of a clustering are a better representation of the points in their cluster.",
    "supporting_evidence_ids": [
      "E2",
      "E3"
    ],
    "abstention_reason": ""
  }
}

