{
  "kc_id": "KC_EVAL_SAMP_003",
  "canonical_name": "k-Fold Cross Validation",
  "definition": {
    "status": "grounded",
    "text": "A model evaluation method that aims to make effective use of all labeled instances in a dataset for both training and testing by randomly partitioning the set into equal-sized subsets; for each run, one subset is used for testing while the remaining subsets are used for training, with the overall test error rate calculated by summing errors across all runs and dividing by the total number of instances.",
    "supporting_evidence_ids": [
      "E3"
    ],
    "abstention_reason": ""
  },
  "scope": {
    "status": "grounded",
    "text": "Cross-validation is used for model assessment (evaluation) and model selection, such as hyper-parameter selection, where it allows for the determination of the best hyper-parameter value and the final classification model by making effective use of every data instance in the training set.",
    "supporting_evidence_ids": [
      "E2",
      "E4"
    ],
    "abstention_reason": ""
  }
}

